// Z generykami:
List<String> names = new ArrayList<>();
names.add("Ala");
// names.add(42); // BLAD KOMPILACJI - Integer nie pasuje do String
String name = names.get(0); // BEZ rzutowania

// Wlasna klasa generyczna:
static class Box<T> {
    private T value;
    Box(T value) { this.value = value; }
    T get() { return value; }
    void set(T value) { this.value = value; }
}
Box<String> stringBox = new Box<>("tekst");
Box<Integer> intBox = new Box<>(123);
